import {hijriData} from './hijri-data.js';
export const DAY=86400000;
export const MIN=Math.floor(Date.UTC(1900,0,1)/DAY);
export const gMonths=['January','February','March','April','May','June','July','August','September','October','November','December'];
export const hMonths=['Muharram','Safar','Rabi I','Rabi II','Jumada I','Jumada II','Rajab','Sha’ban','Ramadan','Shawwal','Dhu al-Qidah','Dhu al-Hijjah'];
const bits=Uint8Array.from(atob(hijriData.bits),c=>c.charCodeAt(0));
const starts=[hijriData.start];for(let i=0;i<hijriData.count;i++)starts.push(starts[i]+29+((bits[i>>3]>>(i%8))&1));
export const MAX=starts.at(-1)-1;
export function today(){const d=new Date();return Math.floor(Date.UTC(d.getFullYear(),d.getMonth(),d.getDate())/DAY)}
export const calendars={
 g:{months:gMonths,label:'Gregorian',parts(n){const d=new Date(n*DAY);return [d.getUTCFullYear(),d.getUTCMonth()+1,d.getUTCDate()]},days(y,m){return new Date(Date.UTC(y,m,0)).getUTCDate()},toDay(y,m,d){return Math.floor(Date.UTC(y,m-1,d)/DAY)}},
 h:{months:hMonths,label:'Hijri',parts(n){if(n<starts[0]||n>MAX)throw Error('Date outside supported Hijri range (AH 1300–1600).');let l=0,r=starts.length-1;while(l+1<r){let m=(l+r)>>1;if(starts[m]<=n)l=m;else r=m}return [1300+Math.floor(l/12),l%12+1,n-starts[l]+1]},days(y,m){const i=(y-1300)*12+m-1;if(i<0||i>=hijriData.count)throw Error('Hijri year must be between 1300 and 1600.');return starts[i+1]-starts[i]},toDay(y,m,d){this.days(y,m);return starts[(y-1300)*12+m-1]+d-1}}
};
export function inputDay(c,y,m,d){const cal=calendars[c];if(!cal||![y,m,d].every(Number.isSafeInteger)||m<1||m>12||d<1||d>cal.days(y,m))throw Error('This date does not exist. Please check the day, month and year.');if(c==='g'&&y<1900)throw Error('Choose a birth date from 1 January 1900 through today.');const n=cal.toDay(y,m,d);if(!Number.isInteger(n)||n<MIN||n>today())throw Error('Choose a birth date from 1 January 1900 through today.');return n}
function anniversary(cal,y,m,d){return cal.toDay(y,m,Math.min(d,cal.days(y,m)))}
export function age(birth,now,c){const cal=calendars[c],[by,bm,bd]=cal.parts(birth),[ny]=cal.parts(now);let years=ny-by;if(anniversary(cal,by+years,bm,bd)>now)years--;const base=anniversary(cal,by+years,bm,bd);let months=0,anchor=base;for(let m=1;m<=11;m++){const idx=bm-1+m,y=by+years+Math.floor(idx/12),month=idx%12+1;const candidate=anniversary(cal,y,month,bd);if(candidate>now)break;months=m;anchor=candidate}return {years,months,days:now-anchor}}
export function nextBirthday(birth,now,c){const cal=calendars[c],[,m,d]=cal.parts(birth);let [y]=cal.parts(now);let day=anniversary(cal,y,m,d);if(day<now)day=anniversary(cal,++y,m,d);return {day,inDays:day-now,turns:y-cal.parts(birth)[0]}}
export function formatDate(n,c='g'){const cal=calendars[c],[y,m,d]=cal.parts(n);return `${d} ${cal.months[m-1]} ${y}${c==='h'?' AH':''}`}
export function weekday(n){return new Intl.DateTimeFormat('en',{weekday:'long',timeZone:'UTC'}).format(new Date(n*DAY))}
export function id(){return b64(crypto.getRandomValues(new Uint8Array(6)))}
function b64(b){return btoa(String.fromCharCode(...b)).replaceAll('+','-').replaceAll('/','_').replace(/=+$/,'')}
function un64(s){if(!/^[\w-]*$/.test(s)||s.length%4===1)throw Error('Invalid link encoding.');return Uint8Array.from(atob(s.replaceAll('-','+').replaceAll('_','/')),c=>c.charCodeAt(0))}
function crc(bytes){let c=0xffffffff;for(const b of bytes){c^=b;for(let i=0;i<8;i++)c=c&1?(c>>>1)^0xedb88320:c>>>1}return (c^0xffffffff)>>>0}
const encoder=new TextEncoder(),decoder=new TextDecoder('utf-8',{fatal:true});
export function validate(records){if(!Array.isArray(records)||records.length>150)throw Error('A family link can hold up to 150 people.');const ids=new Set();for(const p of records){if(!p||typeof p.id!=='string'||!/^[\w-]{8}$/.test(p.id)||ids.has(p.id)||typeof p.name!=='string'||!p.name.trim()||encoder.encode(p.name).length>120||decoder.decode(encoder.encode(p.name))!==p.name||!Number.isInteger(p.day)||p.day<MIN||p.day>today()||!['g','h'].includes(p.calendar))throw Error('The family data contains an invalid or duplicate record.');ids.add(p.id)}return records}
export function encode(records){validate(records);const out=[];const v=n=>{while(n>=128){out.push((n&127)|128);n>>>=7}out.push(n)};v(records.length);for(const p of records){out.push(...un64(p.id));v(p.day-MIN);out.push(p.calendar==='h'?1:0);const name=encoder.encode(p.name);v(name.length);out.push(...name)}let data=new Uint8Array(out.length+4);data.set(out);new DataView(data.buffer).setUint32(out.length,crc(out));const zipped=globalThis.pako.deflate(data,{level:9});return '#k1'+(zipped.length<data.length?'z'+b64(zipped):'r'+b64(data))}
export function decode(hash){if(hash.length>30000)throw Error('This link is too large.');if(!/^#k1[rz]/.test(hash))throw Error('This is not a supported Kin family link.');let data=un64(hash.slice(4));if(hash[3]==='z'){const inflator=new globalThis.pako.Inflate();let chunks=[],total=0;inflator.onData=chunk=>{total+=chunk.length;if(total>21000)throw Error('This link expands beyond the safe size limit.');chunks.push(chunk)};inflator.push(data,true);if(inflator.err||!inflator.ended)throw Error('This link is damaged or incomplete.');data=new Uint8Array(total);let i=0;for(const chunk of chunks){data.set(chunk,i);i+=chunk.length}}
 if(data.length<5||data.length>21000)throw Error('Invalid link size.');const end=data.length-4;if(new DataView(data.buffer,data.byteOffset,data.byteLength).getUint32(end)!==crc(data.slice(0,end)))throw Error('This link is incomplete or has been changed.');let at=0;const byte=()=>{if(at>=end)throw Error('Incomplete family data.');return data[at++]};const v=()=>{let n=0;for(let s=0;s<=21;s+=7){const b=byte();n+=(b&127)*2**s;if(!(b&128))return n}throw Error('Invalid number in link.')};const count=v();if(count>150)throw Error('Too many family members.');const people=[];for(let i=0;i<count;i++){const raw=Array.from({length:6},byte),day=MIN+v(),flag=byte();if(flag>1)throw Error('Unknown calendar.');const len=v();if(len>120||at+len>end)throw Error('Invalid name in link.');const name=decoder.decode(data.slice(at,at+len));at+=len;people.push({id:b64(raw),name,day,calendar:flag?'h':'g'})}if(at!==end)throw Error('Unexpected data in link.');return validate(people)}
export function mergePlan(existing,incoming){const added=[],conflicts=[],duplicates=[],seen=[...existing];for(const p of incoming){const same=seen.find(x=>x.id===p.id);if(same){if(same.name!==p.name||same.day!==p.day||same.calendar!==p.calendar)conflicts.push({local:same,incoming:p});else duplicates.push(p)}else if(seen.some(x=>x.name.normalize().trim().toLocaleLowerCase()===p.name.normalize().trim().toLocaleLowerCase()&&x.day===p.day))duplicates.push(p);else {added.push(p);seen.push(p)}}return {added,conflicts,duplicates}}
export function merge(existing,plan,replaceIds=[],addIds=plan.added.map(p=>p.id)){return validate([...existing.map(p=>replaceIds.includes(p.id)?plan.conflicts.find(c=>c.local.id===p.id).incoming:p),...plan.added.filter(p=>addIds.includes(p.id))])}
